func (q *Queries) WorkflowByName(ctx context.Context, userID uuid.UUID, name string) (ArchiveWorkflow, error) {
	row := q.db.QueryRow(ctx, workflowByName, userID, name)
	var i ArchiveWorkflow
	err := row.Scan(
		&i.ID,
		&i.Name,
		&i.Access,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.UserID,
		&i.Role,
		&i.Source,
		&i.Trigger,
		&i.Hook,
		&i.NextAt,
		&i.CursorAt,
		&i.CursorID,
		&i.Member,
		&i.On,
	)
	return i, err
}

const workflowNames = `-- name: WorkflowNames :many
SELECT name FROM archive.workflow WHERE user_id = $1 ORDER BY name
`

func (q *Queries) WorkflowNames(ctx context.Context, userID uuid.UUID) ([]string, error) {
	rows, err := q.db.Query(ctx, workflowNames, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []string
	for rows.Next() {
		var name string
		if err := rows.Scan(&name); err != nil {
			return nil, err
		}
		items = append(items, name)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const workflowRunTimes = `-- name: WorkflowRunTimes :many
SELECT created_at FROM archive.workflow_run WHERE workflow = $1 AND created_at >= $2::timestamptz
`

func (q *Queries) WorkflowRunTimes(ctx context.Context, workflow uuid.UUID, since time.Time) ([]time.Time, error) {
	rows, err := q.db.Query(ctx, workflowRunTimes, workflow, since)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []time.Time
	for rows.Next() {
		var created_at time.Time
		if err := rows.Scan(&created_at); err != nil {
			return nil, err
		}
		items = append(items, created_at)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
